package ai.decisionos.aside;
import android.app.*;import android.content.*;import android.os.Bundle;import android.view.*;import android.widget.*;import org.json.*;
/** Checks real companion navigation, preserved forms and canonical aliases without changing user records. */
final class CompanionOnlyChecks {
 static void run(GoalInstrumentation i){Bundle result=new Bundle();GoalAgentActivity activity=null;String id=null;try(GoalStore store=new GoalStore(i.getTargetContext())){try{
  id=store.create("fitness","REGRESSION_COMPANION_TEMP","운동",0).optString("id");activity=(GoalAgentActivity)i.startActivitySync(new Intent(i.getTargetContext(),GoalAgentActivity.class).putExtra("goal_id",id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));i.waitForIdleSync();final GoalAgentActivity a=activity;
  i.runOnMainSync(()->{NubiCompanionUi ui=a.chat.companion;LinearLayout mobile=a.chat.box(NubiCompanionUi.WHITE,16);ui.buildSidebar(mobile);i.check(RedesignChecks.texts(mobile).equals(RedesignChecks.texts(ui.sidebar)),"mobile drawer matches tablet sidebar text and order");for(String label:new String[]{"대화","친구","둘러보기","보관함","나의 누비","대화 검색"})i.check(RedesignChecks.find(mobile,label)!=null,"shared sidebar action "+label);i.check(hasText(mobile,"최근 대화")&&hasText(mobile,"+ 새 대화")&&hasText(mobile,"목표 보기"),"shared sidebar recent history and creation actions");});
  for(String page:new String[]{"에이전트 기능","공통 도구","장소·이동","생활 도구","미디어","준비물","모임","일정","캠퍼스","학사일정","할 일","여행 비교","생활 계획","관심 앱","로컬 모델","로컬 제안","수집 설정","웹 브라우저","친구","탐색","작업","내 정보","목표 설정"}){final Throwable[] error={null};i.runOnMainSync(()->{try{a.chat.companion.select(page);}catch(Throwable t){error[0]=t;}});if(error[0]!=null)throw new AssertionError(page,error[0]);i.waitForIdleSync();i.check(a.chat.companion.page.equals(page),"page "+page);i.check(a.findViewById(android.R.id.content)!=null,"same companion host "+page);capture(i,page);i.check(!hasText(a.chat.companion.outer,"Aside Mobile")&&!hasText(a.chat.companion.outer,"작업실로 돌아가기")&&!hasText(a.chat.companion.outer,"쇼핑·전문가"),"no legacy chrome "+page);}
  final String[] modelDraft={""};i.runOnMainSync(()->{a.chat.companion.select("로컬 모델");EditText input=findEdit(a.chat.companion.sideBody,"AI에게 질문");if(input!=null){input.setText("모델 질문 초안");modelDraft[0]=input.getText().toString();}a.chat.companion.select("여행 비교");a.chat.companion.select("로컬 모델");});i.check(modelDraft[0].equals("모델 질문 초안"),"model prompt editable");final String[] retained={""};i.runOnMainSync(()->{EditText field=findEdit(a.chat.companion.sideBody,"AI에게 질문");if(field!=null)retained[0]=field.getText().toString();});i.check(retained[0].equals("모델 질문 초안"),"model prompt retained across panels");i.check(a.chat.companion.panels.size()==10,"ten tools retained inside shell");
  for(Class<?> old:UnifiedToolsActivity.ROUTES){android.content.pm.ActivityInfo info=i.getTargetContext().getPackageManager().getActivityInfo(new ComponentName(i.getTargetContext(),old),0);i.check(info.targetActivity.endsWith("CompanionEntryActivity"),"old shortcut redirects "+old.getSimpleName());}
  i.runOnMainSync(()->{a.chat.companion.select("대화");a.chat.input.setText("통합 UI 초안 유지");a.chat.companion.select("캠퍼스");a.chat.companion.select("대화");});i.check(a.chat.input.getText().toString().equals("통합 UI 초안 유지"),"chat draft preserved across tools");
  String docx=CompanionDocumentPreview.read(new java.io.ByteArrayInputStream(zip("word/document.xml","<w:document xmlns:w='urn:word'><w:p><w:t>한글 예산서</w:t></w:p></w:document>")));i.check(docx.contains("한글 예산서"),"DOCX text preview");String hwpx=CompanionDocumentPreview.read(new java.io.ByteArrayInputStream(zip("Contents/section0.xml","<hp:p xmlns:hp='urn:hancom'><hp:t>한글 문서</hp:t></hp:p>")));i.check(hwpx.contains("한글 문서"),"HWPX text preview");boolean entity=false;try{CompanionDocumentPreview.read(new java.io.ByteArrayInputStream(zip("word/document.xml","<!DOCTYPE x [<!ENTITY external SYSTEM 'file:///etc/passwd'>]><x/>")));}catch(java.io.IOException expected){entity=true;}i.check(entity,"document entity rejected");boolean oversized=false;try{CompanionDocumentPreview.read(new java.io.ByteArrayInputStream(zip("word/document.xml","x".repeat(2097153))));}catch(java.io.IOException expected){oversized=true;}i.check(oversized,"oversized preview rejected");
  i.runOnMainSync(a::finish);
  for(GoalRules.Preset preset:GoalRules.PRESETS){Bundle progress=new Bundle();progress.putString("stream","Checking "+preset.id+"\n");i.sendStatus(1,progress);String temp=store.create(preset.id,"REGRESSION_CAPABILITY_TEMP",preset.topic,0).optString("id");GoalAgentActivity host=null;try{host=(GoalAgentActivity)i.startActivitySync(new Intent(i.getTargetContext(),GoalAgentActivity.class).putExtra("goal_id",temp).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final GoalAgentActivity target=host;i.runOnMainSync(()->target.chat.companion.select("에이전트 기능"));i.waitForIdleSync();for(String[] feature:CompanionCapabilities.forAgent(preset.id))i.check(hasText(host.chat.companion.sideBody,feature[0]),preset.id+" feature "+feature[0]);i.check(host.chat.goalId.equals(temp),preset.id+" keeps goal context");capture(i,"에이전트_"+preset.id);}finally{if(host!=null){final Activity done=host;i.runOnMainSync(done::finish);i.waitForIdleSync();}store.deleteGoal(temp);}}
  result.putString("stream","PASS "+i.checks+" companion-only navigation and preservation checks\n");i.finish(-1,result);
 }finally{if(activity!=null){final Activity a=activity;i.runOnMainSync(a::finish);}if(id!=null)store.deleteGoal(id);}}
 catch(Throwable t){result.putString("stream","FAIL "+t+"\n");i.finish(0,result);}}
 static byte[] zip(String name,String content)throws Exception{java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();try(java.util.zip.ZipOutputStream zip=new java.util.zip.ZipOutputStream(bytes)){zip.putNextEntry(new java.util.zip.ZipEntry(name));zip.write(content.getBytes(java.nio.charset.StandardCharsets.UTF_8));zip.closeEntry();}return bytes.toByteArray();}
 static void capture(Instrumentation i,String page)throws Exception{android.os.SystemClock.sleep(200);android.graphics.Bitmap bitmap=i.getUiAutomation().takeScreenshot();java.io.File dir=new java.io.File(i.getTargetContext().getCacheDir(),"companion-only-captures");dir.mkdirs();try(java.io.FileOutputStream stream=new java.io.FileOutputStream(new java.io.File(dir,page+".png"))){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,stream);}bitmap.recycle();}
 static boolean hasText(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().equals(text))return true;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int n=0;n<g.getChildCount();n++)if(hasText(g.getChildAt(n),text))return true;}return false;}
 static EditText findEdit(View v,String hint){if(v instanceof EditText&&String.valueOf(((EditText)v).getHint()).contains(hint))return (EditText)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int n=0;n<g.getChildCount();n++){EditText e=findEdit(g.getChildAt(n),hint);if(e!=null)return e;}}return null;}
}
